        coroutine.yield()
      end
      BetterUI.shop_market_take(BetterUI.shop_cycle_key)
      if nxt == nil or f >= BetterUI.shop_market_wait then
        BetterUI.shop_market_log("switch cancelled", tostring(idx), tostring(nxt), f)
